using System.Text.RegularExpressions;

namespace Tempest.Infrastructure.Storage;

/// <summary>Only names generated by <see cref="LocalImageStorage"/> are ever written or deleted (no path traversal).</summary>
internal static partial class UploadNames
{
    [GeneratedRegex(@"^[a-f0-9]{32}\.(?:jpg|png|gif|webp)$", RegexOptions.CultureInvariant)]
    public static partial Regex Managed();
}
